-- CPU4:103 Crownfield Eye Hospital | synthetic teaching data only
CREATE DATABASE IF NOT EXISTS crownfield_eye CHARACTER SET utf8mb4;
USE crownfield_eye;
CREATE TABLE patient (patient_id CHAR(5) PRIMARY KEY, full_name VARCHAR(90) NOT NULL, postcode VARCHAR(12) NOT NULL, registered_on DATE NOT NULL, password_salt CHAR(16) NOT NULL, password_hash CHAR(64) NOT NULL);
CREATE TABLE clinician (clinician_id CHAR(5) PRIMARY KEY, clinician_name VARCHAR(90) NOT NULL, specialty VARCHAR(60) NOT NULL, contact_email VARCHAR(120) NOT NULL UNIQUE);
CREATE TABLE clinic (clinic_id CHAR(5) PRIMARY KEY, clinic_name VARCHAR(80) NOT NULL UNIQUE, location VARCHAR(100) NOT NULL);
CREATE TABLE appointment (appointment_id INT PRIMARY KEY AUTO_INCREMENT, patient_id CHAR(5) NOT NULL, clinician_id CHAR(5) NOT NULL, clinic_id CHAR(5) NOT NULL, appointment_date DATE NOT NULL, appointment_time TIME NOT NULL, status ENUM('scheduled','completed','cancelled','rescheduled') NOT NULL DEFAULT 'scheduled', CONSTRAINT uq_slot UNIQUE(clinician_id,appointment_date,appointment_time), CONSTRAINT fk_ap_patient FOREIGN KEY(patient_id) REFERENCES patient(patient_id) ON DELETE RESTRICT, CONSTRAINT fk_ap_clinician FOREIGN KEY(clinician_id) REFERENCES clinician(clinician_id) ON DELETE RESTRICT, CONSTRAINT fk_ap_clinic FOREIGN KEY(clinic_id) REFERENCES clinic(clinic_id) ON DELETE RESTRICT);
CREATE TABLE diagnosis (diagnosis_id INT AUTO_INCREMENT PRIMARY KEY, appointment_id INT NOT NULL, diagnosis_name VARCHAR(100) NOT NULL, notes VARCHAR(255), FOREIGN KEY(appointment_id) REFERENCES appointment(appointment_id) ON DELETE RESTRICT);
CREATE TABLE medication (medication_id INT AUTO_INCREMENT PRIMARY KEY, medicine_name VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE prescription (prescription_id INT AUTO_INCREMENT PRIMARY KEY, appointment_id INT NOT NULL, issued_on DATE NOT NULL, FOREIGN KEY(appointment_id) REFERENCES appointment(appointment_id) ON DELETE RESTRICT);
CREATE TABLE prescription_item (item_id INT AUTO_INCREMENT PRIMARY KEY, prescription_id INT NOT NULL, medication_id INT NOT NULL, dose VARCHAR(60) NOT NULL, route VARCHAR(40) NOT NULL, frequency VARCHAR(60) NOT NULL, duration_days INT NOT NULL, CHECK(duration_days > 0), FOREIGN KEY(prescription_id) REFERENCES prescription(prescription_id) ON DELETE RESTRICT, FOREIGN KEY(medication_id) REFERENCES medication(medication_id) ON DELETE RESTRICT);
CREATE TABLE follow_up (followup_id INT AUTO_INCREMENT PRIMARY KEY, appointment_id INT NOT NULL UNIQUE, due_date DATE NOT NULL, priority ENUM('routine','high','urgent') NOT NULL, status ENUM('open','completed','cancelled') NOT NULL DEFAULT 'open', notes VARCHAR(255), FOREIGN KEY(appointment_id) REFERENCES appointment(appointment_id) ON DELETE RESTRICT);
CREATE TABLE dose_audit (audit_id INT AUTO_INCREMENT PRIMARY KEY, item_id INT NOT NULL, old_dose VARCHAR(60), new_dose VARCHAR(60), changed_by VARCHAR(150) NOT NULL, changed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
-- Confirm counts before taking evidence screenshots
SELECT 'patient' AS table_name,COUNT(*) AS rows_count FROM patient UNION ALL SELECT 'clinician',COUNT(*) FROM clinician UNION ALL SELECT 'clinic',COUNT(*) FROM clinic UNION ALL SELECT 'appointment',COUNT(*) FROM appointment UNION ALL SELECT 'diagnosis',COUNT(*) FROM diagnosis UNION ALL SELECT 'medication',COUNT(*) FROM medication UNION ALL SELECT 'prescription',COUNT(*) FROM prescription UNION ALL SELECT 'prescription_item',COUNT(*) FROM prescription_item UNION ALL SELECT 'follow_up',COUNT(*) FROM follow_up;
